package cl.dynasty.nexusbeacon.platform.classic;
import java.util.Map;import java.util.UUID;import java.util.logging.Logger;import org.bukkit.entity.Player;import org.bukkit.inventory.ItemStack;
final class ClassicPurchaseService {enum Result{COMMITTED,REMOVED,UNAUTHORIZED,UNSUPPORTED,INVALID_LEVEL,INVALID_PRICE,ECONOMY_UNAVAILABLE,INSUFFICIENT_FUNDS,DEBIT_FAILED,PERSISTENCE_FAILED_REFUNDED,PERSISTENCE_FAILED_REFUND_FAILED}private final ClassicApplicationState state;private final ClassicEffectCatalog catalog;private final ClassicPaymentResolver prices;private final ClassicEconomyService economy;private final Logger logger;ClassicPurchaseService(ClassicApplicationState state,ClassicEffectCatalog catalog,org.bukkit.configuration.file.FileConfiguration effects,ClassicEconomyService economy,Logger logger){this.state=state;this.catalog=catalog;prices=new ClassicPaymentResolver(effects);this.economy=economy;this.logger=logger;}String price(UUID beaconId,String effectId,String optionKey){ClassicBeaconRecord current=state.findByUniqueId(beaconId);ClassicEffectCatalog.Definition definition=catalog.get(effectId);if(current==null||definition==null)return "Unavailable";Integer owned=current.getEffects().get(effectId);int level=owned==null?0:owned.intValue(),next=level+1;if(next>definition.getMaxLevel())return "Maximum level";ClassicPaymentOption option=prices.resolve(effectId,level==0?"acquire":"upgrade",optionKey,next);if(option==null)return "Unavailable";if(option.type==ClassicPaymentOption.Type.ITEM)return option.amount+" "+option.material.name();if(option.type==ClassicPaymentOption.Type.EXP_LEVEL)return option.amount+" EXP levels";if(option.type==ClassicPaymentOption.Type.VAULT_MONEY)return option.amount+" money";return "Free";}
 synchronized Result purchase(Player player,UUID beaconId,String effectId,String optionKey){ClassicBeaconRecord current=state.findByUniqueId(beaconId);if(current==null)return Result.REMOVED;UUID actor=player.getUniqueId();if(!player.hasPermission("NexusBeacon.admin")&&!actor.equals(current.getOwner())&&!current.getTrusted().contains(actor))return Result.UNAUTHORIZED;ClassicEffectCatalog.Definition definition=catalog.get(effectId);if(definition==null)return Result.UNSUPPORTED;Integer value=current.getEffects().get(effectId);int level=value==null?0:value.intValue(),next=level+1;if(next>definition.getMaxLevel()||!prices.levelEnabled(effectId,next))return Result.INVALID_LEVEL;ClassicPaymentOption option=prices.resolve(effectId,level==0?"acquire":"upgrade",optionKey,next);if(option==null)return Result.INVALID_PRICE;Result debit=debit(player,option);if(debit!=null)return debit;try{if(!state.update(current.withEffectLevel(effectId,next,level==0)))return refund(player,option);}catch(RuntimeException failure){logger.severe("Classic purchase persistence failed for "+effectId+": "+failure.getMessage());return refund(player,option);}return Result.COMMITTED;}
 private Result debit(Player player,ClassicPaymentOption option){if(option.type==ClassicPaymentOption.Type.NONE)return null;if(option.type==ClassicPaymentOption.Type.EXP_LEVEL){if(player.getLevel()<option.amount)return Result.INSUFFICIENT_FUNDS;player.setLevel(player.getLevel()-option.amount);return null;}if(option.type==ClassicPaymentOption.Type.ITEM){if(!player.getInventory().containsAtLeast(new ItemStack(option.material),option.amount))return Result.INSUFFICIENT_FUNDS;Map<Integer,ItemStack> remainder=player.getInventory().removeItem(new ItemStack(option.material,option.amount));return remainder.isEmpty()?null:Result.DEBIT_FAILED;}if(!economy.isAvailable())return Result.ECONOMY_UNAVAILABLE;if(!economy.has(player,option.amount))return Result.INSUFFICIENT_FUNDS;return economy.withdraw(player,option.amount)?null:Result.DEBIT_FAILED;}
 private Result refund(Player player,ClassicPaymentOption option){boolean ok;if(option.type==ClassicPaymentOption.Type.NONE)ok=true;else if(option.type==ClassicPaymentOption.Type.EXP_LEVEL){player.setLevel(player.getLevel()+option.amount);ok=true;}else if(option.type==ClassicPaymentOption.Type.ITEM)ok=player.getInventory().addItem(new ItemStack(option.material,option.amount)).isEmpty();else ok=economy.deposit(player,option.amount);return ok?Result.PERSISTENCE_FAILED_REFUNDED:Result.PERSISTENCE_FAILED_REFUND_FAILED;}}
